                            best = (len(a1) + len(a2), (r, c), d1, d2, a1, a2)
        return best

    tmpl = None
    for cells in comps:
        b = l_arms(cells)
        if b and (tmpl is None or len(cells) > len(tmpl[0])):
            tmpl = (cells, b)
    out = [row[:] for row in grid]
    if not tmpl:
        return out
    tcells, (_, corner, d1, d2, a1, a2) = tmpl
    tcol = grid[tcells[0][0]][tcells[0][1]]
    arms = [(a1, d1), (a2, d2)]
    harm = None; vdir = None
    for a, d in arms:
        if d[0] == 0:
            harm = a
        else:
            vdir = d
    if harm is None:
        return out
    r_arm = corner[0]
    cs = [c for _, c in harm]
    cmin, cmax = min(cs), max(cs)
    side = -vdir[0]
    tset = set(tcells)
    best = None
    for cells in comps:
